"""Item maps with short paraphrases; no reproduced official checklist text."""
import csv
import json
from pathlib import Path
P = Path(__file__).resolve().parent
STARD = '1|Study identity|ADAPTED|Title; Abstract|Text-reference agreement rather than clinical diagnosis.\n2|Structured abstract|YES|Abstract|Design, methods, results and limitations stated.\n3|Background|YES|Introduction|Registered scans and report correspondence.\n4|Objectives|YES|Introduction|Category recovery, opposition and ambiguity.\n5|Design timing|YES|Methods: Design|Retrospective, later cohort reuse disclosed.\n6|Eligibility|PARTIAL|Methods: Selection|Local criteria explicit; clinical eligibility unknown.\n7|Participant identification|PARTIAL|Methods: Selection|Archive-wide inclusion; source recruitment unverified.\n8|Setting and dates|NO|Methods: Design|Centres and acquisition dates absent.\n9|Series selection|PARTIAL|Methods: Selection|All local eligible files; source recruitment unknown.\n10a|Index details|YES|Methods: Geometry; supplement|Version, features, recipe and code locators.\n10b|Reference details|PARTIAL|Methods: Textual reference|Extraction reproducible; reader training unknown.\n11|Reference rationale|YES|Methods: Textual reference|Existing text, limited observable.\n12a|Index thresholds|YES|Methods: Statistics; supplement|Frozen category/set gates and later history.\n12b|Reference thresholds|PARTIAL|Methods: Textual reference|Text categories explicit; clinical cutoffs unvalidated.\n13a|Index blinding|PARTIAL|Methods: Statistics|Freeze documented; prior parser exposure stated.\n13b|Reference blinding|PARTIAL|Methods: Textual reference|Reports precede model; original blinding unknown.\n14|Statistical methods|YES|Methods: Statistics|Case bootstrap, paired contrasts and Wilson.\n15|Indeterminate results|YES|Methods; Tables 1–3|Missing categories excluded; unknown anatomy retained.\n16|Missing data|YES|Methods: Selection|No reference imputation; empty-geometry refusal.\n17|Variability analyses|ADAPTED|Results: Reports; Discussion|Conflict and scenarios; no clinical subgroup analysis.\n18|Sample size|YES|Methods: Selection|Available archive; no prospective calculation.\n19|Participant flow|YES|Table 1; Figure 1|Branches, denominators and overlapping losses.\n20|Participant characteristics|NO|Methods: Selection|Demographic and scanner distributions unavailable.\n21a|Condition spectrum|ADAPTED|Supplement: distributions|Extracted categories, no disease-standard spectrum.\n21b|Alternative diagnoses|NA|Methods: Design|No disease-status negative group.\n22|Timing and interventions|PARTIAL|Methods: Design|Static pairing; acquisition/report interval unknown.\n23|Cross-tabulation|YES|confusion_matrices.csv|Reported category confusion counts supplied.\n24|Accuracy and precision|ADAPTED|Tables 2–4|Text agreement intervals; no clinical accuracy.\n25|Adverse events|NA|Methods: Design|Retrospective computation, no intervention.\n26|Limitations|YES|Discussion|Parser, anatomy, contact and reused cohort.\n27|Implications|YES|Discussion; Conclusion|Lab prioritization, no treatment advice.\n28|Registration|NO|Methods; supplement|Local files; no public prospective registration.\n29|Protocol access|PARTIAL|Declarations; supplement|Private manifests; no public protocol link.\n30|Funding|NO|Declarations|Investigator statement pending.'
CLAIM = '1|AI identification|YES|Title; Abstract|Machine learning and geometry distinguished.\n2|Abstract|YES|Abstract|Retrospective data, sample and limits.\n3|Background|YES|Introduction|Research role and existing method.\n4|Study aims|YES|Introduction|Capability and information-link questions.\n5|Design timing|YES|Methods: Design|Retrospective study.\n6|Study goal|YES|Methods: Design|Lab research output, no deployment.\n7|Data sources|PARTIAL|Methods; References|Source links; exact license unresolved.\n8|Eligibility|PARTIAL|Methods: Selection|Local criteria; clinical recruitment unknown.\n9|Preprocessing|YES|Methods: Geometry; supplement|Sampling, frame and source revision.\n10|Subset selection|YES|Methods: Selection|Scan input and endpoint label rules.\n11|De-identification|PARTIAL|Methods: Design|Anonymous IDs; source process unverified.\n12|Missing data|YES|Methods: Selection|No negative imputation; endpoint exclusions.\n13|Acquisition protocol|NO|Methods: Selection|Scanner/calibration details absent.\n14|Reference definition|PARTIAL|Methods: Textual reference|Rules explicit; clinical annotation protocol absent.\n15|Reference rationale|YES|Methods: Textual reference|Stated findings answer narrow question.\n16|Annotator provenance|PARTIAL|Methods: Textual reference|Clinician authorship; case-linked qualifications absent.\n17|Test annotation|PARTIAL|Methods; supplement|Parser sources; no independent adjudication.\n18|Rater variability|ADAPTED|Table 4; Discussion|Report conflicts, no identified interrater study.\n19|Partition assignment|YES|Methods: Selection|Case hash and cohort history.\n20|Disjoint level|PARTIAL|Methods: Selection|Case-disjoint; person lineage unverified.\n21|Test size|YES|Methods: Selection|Available data, no prospective power.\n22|Model description|PARTIAL|Methods: Geometry; supplement|Boosting recipe and parent code locators given; complete segmentation architecture/layer specification absent.\n23|Software versions|PARTIAL|Supplement|Reporting environment is recorded; full training/inference versions are referenced in parent files rather than listed here.\n24|Initialization|PARTIAL|Methods; supplement|Boosting seeds stated; starting neural weights and initialization distributions are not fully described.\n25|Training details|PARTIAL|Methods; supplement|Boosting recipes explicit; neural optimizer, augmentation, stopping and all hyperparameters remain in parent code.\n26|Model selection|PARTIAL|Methods; Discussion|Later representations use inspected cohort.\n27|Ensembling|NA|Methods: Geometry|Per-field models; no classifier fusion.\n28|Metrics|YES|Methods: Statistics|Agreement, balanced accuracy, kappa and coverage.\n29|Uncertainty|YES|Methods; Tables|Case intervals and limited scope.\n30|Robustness|PARTIAL|Discussion; supplement|Rotation/scenarios; clinical transfer unknown.\n31|Interpretability|PARTIAL|Methods; Discussion|Geometric witnesses; anatomy unvalidated.\n32|Internal testing|YES|Methods; Results|Original partition, exposure and cohort reuse.\n33|External testing|NO|Discussion|No separate clinical cohort.\n34|Trial registration|NA|Methods: Design|No trial or intervention.\n35|Data flow|YES|Table 1; Figure 1|Exclusions and unassigned faces with reasons.\n36|Case characteristics|NO|Methods: Selection|Demographics and centre distributions unavailable.\n37|Performance results|PARTIAL|Tables; supplement|Internal endpoints; demographic strata unavailable.\n38|Diagnostic precision|ADAPTED|Methods; Tables|Textual agreement, no diagnosis standard.\n39|Failure analysis|YES|Results; confusion CSV|Parser, singleton and geometry errors.\n40|Limitations|YES|Discussion|Reference, exposure, anatomy and contact.\n41|Implications|YES|Discussion; Conclusion|Matched lab measurement and research use.\n42|Protocol access|PARTIAL|Declarations; supplement|Private sources, public protocol absent.\n43|Resource availability|PARTIAL|Declarations; README_DEMO|Local artifacts; public deposit/rights unresolved.\n44|Funding|NO|Declarations|Investigator statements pending.'

def parse(raw, scheme):
    return [dict(scheme=scheme, item=i, short_paraphrase=t, status=s, location=l, reason=r) for (i, t, s, l, r) in [line.split('|') for line in raw.splitlines()]]
rows = parse(STARD, 'STARD_2015') + parse(CLAIM, 'CLAIM_2024')
assert len(rows) == 78
with (P / 'tables/reporting_checklist.csv').open('w') as f:
    w = csv.DictWriter(f, fieldnames=list(rows[0]))
    w.writeheader()
    w.writerows(rows)
text = '# Reporting checklist: STARD 2015 and CLAIM 2024\n\nLabels are short paraphrases, not official text. STARD is adapted to category agreement with clinician-authored text; CLAIM applies to the imaging/machine-learning components. ADAPTED is outside a literal clinical-accuracy interpretation. YES means documented here, not scientifically validated. PARTIAL/NO are open reporting facts. No completeness or quality score is claimed.\n\nSources: [STARD statement](https://doi.org/10.1136/bmj.h5527), [official checklist](https://www.equator-network.org/wp-content/uploads/2015/03/STARD-2015-checklist.pdf), [CLAIM 2024](https://doi.org/10.1148/ryai.240300). DOI identities are saved in sources/DOI_VERIFICATION.json.\n'
for scheme in ['STARD_2015', 'CLAIM_2024']:
    text += '\n## ' + scheme.replace('_', ' ') + '\n\n| Item | Short paraphrase | Status | Manuscript location | Remaining fact or scope |\n| --- | --- | --- | --- | --- |\n'
    for r in rows:
        if r['scheme'] == scheme:
            text += '| ' + ' | '.join((r[k] for k in ['item', 'short_paraphrase', 'status', 'location', 'reason'])) + ' |\n'
text += '\n## Before submission\n\nSupply authorship, funding/conflicts, secondary-use ethics determination and exact dataset/code rights. Independently adjudicate reference categories, document acquisition/reader details, and obtain untouched external testing. These are present factual gaps; no posting or submission was performed.\n'
(P / 'CHECKLIST.md').write_text(text)
(P / 'CHECKLIST.json').write_text(json.dumps(dict(status='INCOMPLETE_REPORTING', formal_compliance_claim=False, items=rows), indent=2) + '\n')
print('78 STARD/CLAIM mappings written; incomplete reporting stated.')
